// Bundle lib/welcome/whale-animation.js (an ES module) into a classic script the
// sandboxed welcome window can load with a plain <script src>. The welcome page
// has a strict CSP ('self' only) and no bundler, so the module's `export`
// statements must be stripped and its symbols published on `window`.
//
// Usage: node vendor/whale/bundle.mjs <srcModule> <outFile>
import { readFile, writeFile } from 'node:fs/promises'
import path from 'node:path'
// 项目根从唯一的接口模块拿 —— 不要在这里用 `path.resolve(here,'..')` 自己推一份（两份推算迟早不一致）。
import { PROJECT_ROOT } from '../lib/harness.mjs'

const [src, out] = process.argv.slice(2)
if (src === undefined || out === undefined) {
  console.error('usage: node bundle-whale.mjs <srcModule> <outFile>')
  process.exit(2)
}

const text = await readFile(src, 'utf8')
// Preserve the exact supplied PNG bytes. Embedded data is origin-clean for
// WebGL even when the preview is opened directly from file://.
const whaleImage = await readFile(path.join(path.dirname(src), 'whale-3d.png'))

// Collect the trailing `export { ... }` / `export { ... }` and `export function`
// declarations, then rewrite them as window assignments.
const exported = new Set()

// `export function name(...)` -> `function name(...)`
let body = text.replace(/^export function (\w+)/gm, (_m, name) => {
  exported.add(name)
  return `function ${name}`
})
body = body.replace("const WHALE_IMAGE_DATA = ''", `const WHALE_IMAGE_DATA = 'data:image/png;base64,${whaleImage.toString('base64')}'`)
// `export class Name` -> `class Name`
body = body.replace(/^export class (\w+)/gm, (_m, name) => {
  exported.add(name)
  return `class ${name}`
})
// `export const NAME = ...` / `export let`
body = body.replace(/^export (const|let|var) (\w+)/gm, (_m, kind, name) => {
  exported.add(name)
  return `${kind} ${name}`
})
// Trailing `export { a, b, c }` (possibly with aliases) -> nothing; names collected.
body = body.replace(/^export \{([^}]*)\}\s*$/gm, (_m, names) => {
  for (const part of names.split(',')) {
    const trimmed = part.trim()
    if (trimmed === '') continue
    const alias = trimmed.split(/\s+as\s+/)
    exported.add((alias[1] ?? alias[0]).trim())
  }
  return ''
})

// 产物里的 banner 要写清「从哪一份源生成」—— 但绝不硬编码路径（曾经写死 `../../.probe/build/...`，
// 素材一搬位置，那句话就变成假话）。改成按**相对项目根**的写法，搬位置自动跟着变。
const srcLabel = (() => {
  const rel = path.relative(PROJECT_ROOT, path.resolve(src))
  return rel.startsWith('..') ? path.resolve(src) : rel.split(path.sep).join('/')
})()

const banner = `/**
 * GENERATED from ${srcLabel} by vendor/whale/bundle.mjs.
 * Do not edit this file directly: edit the module and re-run the bundler.
 */
;(() => {
'use strict'
`
const footer = `
// Publish the module's public surface for the classic-script consumer.
window.WhaleSplash = WhaleSplash
window.whalePath = whalePath
window.drawWhale = drawWhale
window.__WHALE_PIXEL__ = PIXEL
})()
`

await writeFile(out, `${banner}${body}\n${footer}`, 'utf8')
console.log(`bundled ${src} -> ${out} (${body.length} bytes body, exports: ${[...exported].join(', ')})`)
